INSERT INTO public.catalog(key,data) VALUES ('costumes','[{"id": "cone", "cost": 0.012, "kind": "hat", "mins": 45, "name": "Traffic Cone", "note": "Placed. Not explained."}, {"id": "party", "cost": 0.012, "kind": "hat", "mins": 45, "name": "Party Hat", "note": "It is nobody''s birthday."}, {"id": "hardhat", "cost": 0.014, "kind": "hat", "mins": 45, "name": "Hard Hat", "note": "No construction is occurring."}, {"id": "visor", "cost": 0.014, "kind": "hat", "mins": 45, "name": "Accounting Visor", "note": "Green. Translucent. Unearned."}, {"id": "kilt", "cost": 0.02, "kind": "body", "mins": 45, "name": "Business Kilt", "note": "Formal. Ventilated. Non-negotiable."}, {"id": "robe", "cost": 0.018, "kind": "body", "mins": 45, "name": "Bathrobe", "note": "Works from home now, apparently."}, {"id": "hawaii", "cost": 0.016, "kind": "body", "mins": 45, "name": "Hawaiian Shirt", "note": "Mentally on vacation. Physically at the printer."}, {"id": "suit", "cost": 0.022, "kind": "body", "mins": 45, "name": "Interview Suit", "note": "Three pieces. Everyone noticed."}, {"id": "trex", "cost": 0.03, "kind": "body", "mins": 45, "name": "Inflatable T-Rex", "note": "Cannot reach the keyboard. Still on payroll."}, {"id": "mascot", "cost": 0.035, "kind": "body", "mins": 45, "name": "Patron the Ledger Lynx", "note": "The mascot nobody approved."}, {"id": "board", "cost": 0.025, "kind": "body", "mins": 45, "name": "Sandwich Board", "note": "Reads: ASK ME ABOUT SYNERGY."}]'::jsonb);
