INSERT INTO public.catalog(key,data) VALUES ('depts','[{"id": "development", "name": "Development", "note": "Ships at 11pm. Mentions it at 9am.", "perk": "Clicking pays 3x"}, {"id": "contracts", "name": "Contracts", "note": "Has read it twice. It is still bad.", "perk": "Deeds cost 30% less"}, {"id": "resale", "name": "Resale", "note": "Knows what everything on the pallet is worth.", "perk": "Staff cost 10% less"}, {"id": "finance", "name": "Finance", "note": "A tab for every entity. More tabs than entities.", "perk": "+12% output, always"}, {"id": "property", "name": "Property", "note": "Rent in, maintenance out, folder for everything.", "perk": "Earn offline for 12 hours, not 8"}, {"id": "systems", "name": "Systems", "note": "Keeps it running. Nobody notices until it stops.", "perk": "Everything done to you is 40% weaker"}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('drinks','[{"id": "espresso", "mins": 6, "mult": 1.35, "name": "Double Espresso", "note": "It grinds the beans in front of you. Ninety seconds. Worth it.", "where": "coffee"}, {"id": "drip", "mins": 30, "mult": 1.1, "name": "Long Black", "note": "Less of a spike. Lasts most of an afternoon.", "where": "coffee"}, {"id": "flat", "mins": 18, "mult": 1.18, "name": "Flat White", "note": "The machine does the milk. Nobody knows how. Nobody asks.", "where": "coffee"}, {"id": "energy", "mins": 4, "mult": 1.6, "name": "Energy Drink", "note": "Enormous for four minutes. Then a well-earned trough.", "crash": 0.85, "where": "fridge", "crash_mins": 8}, {"id": "protein", "mins": 25, "mult": 1.2, "name": "Protein Shake", "note": "Chalky. Effective. Somebody else''s, probably.", "where": "fridge"}, {"id": "soda", "mins": 12, "mult": 1.15, "name": "Soda", "note": "The good flavour is always gone by Wednesday.", "where": "fridge"}, {"id": "water", "mins": 0, "name": "Water", "note": "Clears whatever anyone did to you. Hydration is a counterspell.", "where": "fridge", "clears": true}, {"id": "light", "mins": 25, "mult": 1.45, "name": "Merican Light", "note": "The work beer. Crisp, forgiving, faintly patriotic.", "crash": 0.9, "where": "cooler", "after_hour": 11, "crash_mins": 10}, {"id": "lager", "mins": 18, "mult": 1.7, "name": "Merican Lager", "note": "Heavier. You will feel this one around 3pm.", "crash": 0.8, "where": "cooler", "after_hour": 11, "crash_mins": 14}, {"id": "ipa", "mins": 12, "mult": 2.1, "name": "Merican IPA", "note": "Enormous, then regrettable. Everyone tries it once.", "crash": 0.7, "where": "cooler", "after_hour": 11, "crash_mins": 20}, {"id": "na", "mins": 30, "mult": 1.12, "name": "Merican Zero", "note": "All of the ritual, none of the consequences. Available any time.", "where": "cooler", "after_hour": 0}, {"id": "coldbrew", "mins": 22, "mult": 1.28, "name": "Cold Brew", "note": "Steeped for twelve hours by someone with a system.", "where": "fridge"}]'::jsonb);
