INSERT INTO public.catalog(key,data) VALUES ('items','[{"id": "intern", "cost": 15, "name": "Office Intern", "note": "Helps with tasks and learns the ropes.", "rate": 0.25}, {"id": "poster", "cost": 330, "name": "Motivational Poster", "note": "A kitten hangs from a branch. HR has classified this as a raise.", "rate": 4.12}, {"id": "coffee", "cost": 7260, "name": "Break Room Coffee Machine", "note": "Grinds beans. Grinds people. Mostly people.", "rate": 68}, {"id": "manager", "cost": 160000, "name": "Middle Manager", "note": "Produces nothing measurable. Output rises anyway. Do not investigate.", "rate": 1120}, {"id": "desk", "cost": 3510000, "name": "Standing Desk Initiative", "note": "Nobody stands. Everybody mentions that they could.", "rate": 18500}, {"id": "board", "cost": 77300000, "name": "Synergy Whiteboard", "note": "Covered in arrows. The arrows point at other arrows.", "rate": 306000}, {"id": "openplan", "cost": 1700000000, "name": "Open-Plan Renovation", "note": "Walls removed to encourage collaboration and despair.", "rate": 5040000}, {"id": "allhands", "cost": 37400000000, "name": "Quarterly All-Hands", "note": "Ninety minutes. One slide. Everyone claps at the end, unclear why.", "rate": 83200000}, {"id": "satellite", "cost": 823000000000, "name": "Offshore Satellite Office", "note": "Eleven time zones away. Always somehow already awake.", "rate": 1370000000}, {"id": "bot", "cost": 18100000000000, "name": "Sentient Slack Bot", "note": "Started as a standup reminder. Now approves invoices.", "rate": 22600000000}, {"id": "vending", "cost": 398000000000000, "name": "The Vending Machine That Knows", "note": "It stocks your favorite snack the day before you crave it.", "rate": 373000000000}, {"id": "retreat", "cost": 8760000000000000, "name": "Mandatory Spiritual Retreat", "note": "Trust falls at altitude. Several people come back different.", "rate": 6160000000000}, {"id": "subsidiary", "cost": 193000000000000000, "name": "Wholly Owned Subsidiary", "note": "It has its own Dave Their leaderboard is worse than ours.", "rate": 102000000000000}, {"id": "holiday", "cost": 4240000000000000000, "name": "Company Holiday Named After You", "note": "Observed regionally. Banks close. Nobody is sure why.", "rate": 1680000000000000}, {"id": "regional", "cost": 93300000000000000000, "name": "Regional Monopoly", "note": "Competitors are referred to internally as \"the others\".", "rate": 27700000000000000}, {"id": "boardseat", "cost": 2.05e+21, "name": "A Seat On The Board", "note": "You now sit in the meeting you used to be summoned to.", "rate": 456000000000000000}, {"id": "building", "cost": 4.52e+22, "name": "The Building Is Ours", "note": "The landlord works here now. He seems fine about it.", "rate": 7530000000000000000}, {"id": "secondpg", "cost": 9.94e+23, "name": "A Second Patron Group", "note": "Identical to this one. Slightly better coffee. Do not visit.", "rate": 124000000000000000000}, {"id": "franchise", "cost": 2.19e+25, "name": "A Franchise Model", "note": "Other people run it. You take a percentage. This is the dream, apparently.", "rate": 2.73e+21}, {"id": "holding", "cost": 4.81e+26, "name": "A Holding Company", "note": "It owns the other things. Nobody can explain what it does. It does it well.", "rate": 6.01e+22}, {"id": "sovereign", "cost": 1.06e+28, "name": "A Sovereign Wealth Fund", "note": "A small nation now depends on your quarterly numbers. Nobody told them.", "rate": 1.32e+24}, {"id": "annex", "cost": 2.33e+29, "name": "The Orbital Annex", "note": "Low earth orbit. No commute. Legal has stopped returning calls.", "rate": 2.91e+25}, {"id": "timezone", "cost": 5.12e+30, "name": "Your Own Time Zone", "note": "Patron Standard Time. Twenty six hours. Nobody has objected loudly enough.", "rate": 6.4e+26}, {"id": "original", "cost": 1.13e+32, "name": "The Original Patron Group", "note": "It turns out there was one before this one. You have acquired it. Do not ask.", "rate": 1.41e+28}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('mail','[{"w": 18, "id": "payslip", "kind": "pp", "text": "A payslip. The number is correct, which is somehow worse.", "amount": 300}, {"w": 22, "id": "memo", "kind": "none", "text": "An internal memo about memo formatting. It is incorrectly formatted."}, {"w": 16, "id": "snack", "kind": "buff", "mins": 25, "mult": 1.15, "text": "A snack in a plain wrapper. No sender. You eat it immediately."}, {"w": 8, "id": "cheque", "kind": "pp", "text": "An expense reimbursement from a quarter nobody remembers.", "amount": 900}, {"w": 14, "id": "note", "kind": "none", "text": "An anonymous note. It says: I know what you did with the chair."}, {"w": 12, "id": "catalog", "kind": "none", "text": "A catalogue of office furniture. Somebody has circled a chair. Not the good one."}, {"w": 6, "id": "jury", "kind": "none", "text": "Jury duty. Not for you. It is addressed to somebody who left in 2019."}, {"w": 4, "id": "bonus", "kind": "pp", "text": "A discretionary bonus. No explanation. Do not ask Dave.", "amount": 2500}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('meeting','{"done": "The meeting is over. Nothing was decided.", "room": "Conference Room B", "alone": "You attended. Nobody else did. The minutes will reflect that.", "blurb": "No agenda. No materials. Attendance is the entire deliverable.", "called": "A meeting has been called in Conference Room B.", "cap_secs": 9000, "window_secs": 120, "per_pair_secs": 600}'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('office_goal','{"won": "MARGARITA FRIDAY. Everyone doubles for 24 hours and the machine stays in the break room while the streak lives.", "name": "The Margarita Machine", "blurb": "Everybody has talked about it for years. Nobody has ordered it.", "floor": 4e+27, "growth": 1.75, "max_jump": 6, "per_player": 1.2e+27, "vs_last_week": 0.9}'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('office_kit','[{"id": "d1", "cost": 8e+23, "name": "A Desk Without A Wobble", "note": "Four legs, all touching the floor. This was not always true.", "secs": 400, "slot": "desk", "tier": 1}, {"id": "d2", "cost": 9.6e+24, "name": "Glass Top", "note": "Shows every fingerprint. Worth it.", "secs": 2400, "slot": "desk", "tier": 2}, {"id": "d3", "cost": 1.1e+26, "name": "Walnut, Or Close Enough", "note": "Veneer. Convincing veneer. Nobody is going to check.", "secs": 14400, "slot": "desk", "tier": 3}, {"id": "d4", "cost": 1.4e+27, "name": "Actual Marble", "note": "The floor beneath it has been surveyed. It was fine. Probably.", "secs": 86400, "slot": "desk", "tier": 4}, {"id": "d5", "cost": 1.7e+28, "name": "Something Black And Seamless", "note": "No drawers. No edges. No explanation.", "secs": 518400, "slot": "desk", "tier": 5}, {"id": "c1", "cost": 2e+24, "name": "A Chair That Goes Up", "note": "The lever works. It has never worked before.", "secs": 700, "slot": "chair", "tier": 1}, {"id": "c2", "cost": 2.4e+25, "name": "Lumbar Support", "note": "You have opinions about it now. You share them.", "secs": 4900, "slot": "chair", "tier": 2}, {"id": "c3", "cost": 2.9e+26, "name": "The Mesh One From The Catalogue", "note": "The one everybody looked at and nobody ordered.", "secs": 34300, "slot": "chair", "tier": 3}, {"id": "c4", "cost": 3.5e+27, "name": "Leather. Reclining. Silent.", "note": "It makes no sound at all. This unsettles visitors.", "secs": 240000, "slot": "chair", "tier": 4}, {"id": "r1", "cost": 1.5e+24, "name": "A Rug, Finally", "note": "Covers the stain. Everyone knows about the stain.", "secs": 500, "slot": "rug", "tier": 1}, {"id": "r2", "cost": 1.8e+25, "name": "Something With A Pattern", "note": "Geometric. Inoffensive. Chosen by committee.", "secs": 3500, "slot": "rug", "tier": 2}, {"id": "r3", "cost": 2.2e+26, "name": "A Rug People Comment On", "note": "Two people have asked where it is from. You have not told them.", "secs": 24500, "slot": "rug", "tier": 3}, {"id": "r4", "cost": 2.6e+27, "name": "Handwoven, Allegedly", "note": "The invoice said handwoven. The invoice said a lot of things.", "secs": 171500, "slot": "rug", "tier": 4}, {"id": "w1", "cost": 3e+24, "name": "A Motivational Print", "note": "PERSEVERANCE. A canoe. Nobody has looked at it twice.", "secs": 1200, "slot": "art", "tier": 1}, {"id": "w2", "cost": 3.6e+25, "name": "A Framed Certificate", "note": "Completion, not achievement. The distinction is not visible from the door.", "secs": 8400, "slot": "art", "tier": 2}, {"id": "w3", "cost": 4.3e+26, "name": "An Actual Painting", "note": "Nobody knows who chose it. It has grown on everybody.", "secs": 58800, "slot": "art", "tier": 3}, {"id": "w4", "cost": 5.2e+27, "name": "The Founder Portrait", "note": "It is not Dave. Nobody will say who it is.", "secs": 411600, "slot": "art", "tier": 4}, {"id": "tv1", "name": "The Productivity Flatscreen", "note": "One channel. Four Springer moments. HR has classified it as conflict-resolution training.", "secs": 259200, "slot": "tv", "tier": 1, "min_cost": 50000000}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('perks','[{"id": "deep_pockets", "max": 3, "cost": 3, "name": "Deep Pockets", "note": "+4 hours of offline earnings, each."}, {"id": "compound", "max": 5, "cost": 4, "name": "Compounding Interest", "note": "+5% output, permanently, each."}, {"id": "thick_skin", "max": 2, "cost": 5, "name": "Thick Skin", "note": "Incoming sabotage 25% weaker, each."}, {"id": "silver_tongue", "max": 3, "cost": 4, "name": "Silver Tongue", "note": "One minute off the deed cooldown, each."}, {"id": "good_hands", "max": 2, "cost": 3, "name": "Quick Hands", "note": "The good chair sticks around longer, each."}]'::jsonb);
