INSERT INTO public.catalog(key,data) VALUES ('upgrades','[{"t": "item", "id": "u1", "req": ["intern", 3], "cost": 270, "mult": 2, "name": "Second Monitor", "note": "One screen for work. One for the other thing.", "target": "intern"}, {"t": "item", "id": "u2", "req": ["poster", 3], "cost": 5940, "mult": 2, "name": "Laminator Access", "note": "Laminated posters are 100% more binding, legally.", "target": "poster"}, {"t": "click", "id": "u3", "req": ["intern", 10], "cost": 900, "mult": 3, "name": "Ergonomic Keyboard", "note": "Clicks twice as loud, three times as billable."}, {"t": "item", "id": "u4", "req": ["coffee", 5], "cost": 218000, "mult": 2, "name": "Dark Roast Only", "note": "Cream is now a personal choice, made privately, at home.", "target": "coffee"}, {"t": "item", "id": "u5", "req": ["manager", 5], "cost": 4800000, "mult": 2, "name": "Skip-Level 1:1s", "note": "Managers now report to managers who report to nobody.", "target": "manager"}, {"t": "all", "id": "u6", "req": ["coffee", 12], "cost": 523000, "mult": 1.15, "name": "Company Caffeine Policy", "note": "Mandatory alertness. Voluntary participation. Both, somehow."}, {"t": "item", "id": "u7", "req": ["desk", 8], "cost": 168000000, "mult": 2.5, "name": "Anti-Fatigue Mats", "note": "The standing desks remain unused, but now comfortably so.", "target": "desk"}, {"t": "item", "id": "u8", "req": ["board", 6], "cost": 2780000000, "mult": 2.5, "name": "Marker Amnesty Program", "note": "Return the markers. No questions. No punishment. Just return them.", "target": "board"}, {"t": "all", "id": "u9", "req": ["openplan", 5], "cost": 51000000000, "mult": 1.2, "name": "Noise-Cancelling Everything", "note": "The open plan remains. It is simply no longer audible."}, {"t": "item", "id": "u10", "req": ["allhands", 5], "cost": 1120000000000, "mult": 3, "name": "Slide Deck Automation", "note": "Same deck each quarter. Only the year changes. Nobody notices.", "target": "allhands"}, {"t": "all", "id": "u11", "req": ["satellite", 5], "cost": 24700000000000, "mult": 1.25, "name": "Follow-the-Sun Coverage", "note": "Work never sleeps. Work has never slept. Work does not sleep."}, {"t": "all", "id": "u12", "req": ["bot", 5], "cost": 543000000000000, "mult": 1.4, "name": "Give The Bot Admin", "note": "It asked politely. It asked again. It stopped asking."}, {"t": "all", "id": "u13", "req": ["retreat", 5], "cost": 263000000000000000, "mult": 1.3, "name": "Company Jet (Timeshare)", "note": "Eleven other companies also own it. You have never seen it."}, {"t": "all", "id": "u14", "req": ["holiday", 3], "cost": 76300000000000000000, "mult": 1.35, "name": "Nap Room Access", "note": "It finally exists. There is a waiting list."}, {"t": "item", "id": "m1", "req": ["intern", 25], "cost": 2250, "mult": 2, "name": "Intern Orientation", "note": "Someone finally explained the printer to them. They understood none of it.", "target": "intern"}, {"t": "item", "id": "m2", "req": ["intern", 50], "cost": 4500, "mult": 2, "name": "Intern Pipeline", "note": "A university now sends them automatically. Nobody signed anything.", "target": "intern"}, {"t": "item", "id": "m3", "req": ["poster", 25], "cost": 49500, "mult": 2, "name": "Laminated Everything", "note": "The kitten is now waterproof and, arguably, immortal.", "target": "poster"}, {"t": "item", "id": "m4", "req": ["coffee", 25], "cost": 1090000, "mult": 2, "name": "Second Grinder", "note": "Two grinders. One works. Nobody agrees on which.", "target": "coffee"}, {"t": "item", "id": "m5", "req": ["manager", 25], "cost": 24000000, "mult": 2, "name": "Org Chart Redesign", "note": "Now circular. Everyone reports to everyone. Output doubled. Do not investigate.", "target": "manager"}, {"t": "item", "id": "m6", "req": ["desk", 25], "cost": 526000000, "mult": 2, "name": "Sit-Stand Mandate", "note": "Standing is now compulsory for four minutes a day, unmonitored.", "target": "desk"}, {"t": "item", "id": "m7", "req": ["board", 25], "cost": 11600000000, "mult": 2, "name": "Whiteboard Wall", "note": "Every wall is now a whiteboard. Including the windows. Especially the windows.", "target": "board"}, {"t": "item", "id": "m8", "req": ["openplan", 25], "cost": 255000000000, "mult": 2, "name": "Remove The Last Wall", "note": "There was one wall left. There is no longer one wall left.", "target": "openplan"}, {"t": "item", "id": "m9", "req": ["allhands", 25], "cost": 5610000000000, "mult": 2, "name": "All-Hands, All Week", "note": "The quarterly is now continuous. Attendance is assumed.", "target": "allhands"}, {"t": "item", "id": "m10", "req": ["satellite", 25], "cost": 123000000000000, "mult": 2, "name": "Follow-The-Moon Coverage", "note": "An office on a timezone that does not officially exist.", "target": "satellite"}, {"t": "item", "id": "m11", "req": ["bot", 25], "cost": 2720000000000000, "mult": 2, "name": "Give The Bot A Deputy", "note": "It hired the deputy itself. The deputy is also the bot.", "target": "bot"}, {"t": "item", "id": "m12", "req": ["vending", 25], "cost": 59700000000000000, "mult": 2, "name": "Vending Fleet", "note": "They have begun stocking each other.", "target": "vending"}, {"t": "click", "id": "m13", "req": ["intern", 40], "cost": 3600, "mult": 3, "name": "Mechanical Keyboard", "note": "Audible from the parking lot. Three times as productive, allegedly."}, {"t": "click", "id": "m14", "req": ["desk", 20], "cost": 421000000, "mult": 2, "name": "Two Monitors, Vertically", "note": "Nobody knows why. Everyone respects it."}, {"t": "all", "id": "m15", "req": ["manager", 40], "cost": 38400000, "mult": 1.2, "name": "The Company Handbook", "note": "Ninety pages. Two are read. Those two are load-bearing."}, {"t": "all", "id": "m16", "req": ["allhands", 15], "cost": 3370000000000, "mult": 1.25, "name": "Mandatory Offsite", "note": "A hotel conference room ninety minutes away. Nobody knows whose idea it was."}, {"t": "all", "id": "m17", "req": ["subsidiary", 10], "cost": 11600000000000000000, "mult": 1.3, "name": "Restructure The Restructure", "note": "The subsidiary has a subsidiary. It is doing better than we are."}, {"t": "item", "id": "franchise10", "req": ["franchise", 10], "cost": 1.31e+27, "mult": 2, "name": "Franchise handbook", "note": "Laminated. Nobody reads it. Everybody follows it.", "target": "franchise"}, {"t": "item", "id": "franchise25", "req": ["franchise", 25], "cost": 3.29e+27, "mult": 2, "name": "Regional director", "note": "Drives between them. Owns a lot of polo shirts.", "target": "franchise"}, {"t": "item", "id": "holding10", "req": ["holding", 10], "cost": 2.89e+28, "mult": 2, "name": "A second letterhead", "note": "Same building. Different name. Different tax position.", "target": "holding"}, {"t": "item", "id": "holding25", "req": ["holding", 25], "cost": 7.22e+28, "mult": 2, "name": "An offshore lawyer", "note": "Answers in one sentence. Charges for four.", "target": "holding"}, {"t": "item", "id": "sovereign10", "req": ["sovereign", 10], "cost": 6.36e+29, "mult": 2, "name": "A ratings upgrade", "note": "Somebody in a suit decided you are now safe. You did not change.", "target": "sovereign"}, {"t": "item", "id": "annex10", "req": ["annex", 10], "cost": 1.4e+31, "mult": 2, "name": "A second launch window", "note": "Twice the annex. Half the oxygen budget. Nobody has raised it.", "target": "annex"}, {"t": "item", "id": "timezone10", "req": ["timezone", 10], "cost": 3.07e+32, "mult": 2, "name": "Daylight saving, abolished", "note": "You simply stopped doing it. The sun has not commented.", "target": "timezone"}, {"t": "item", "id": "original10", "req": ["original", 10], "cost": 6.78e+33, "mult": 2, "name": "The founding documents", "note": "Handwritten. Unsigned. The wording is unsettling.", "target": "original"}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('vanity','[{"id": "g1", "cost": 6e+23, "name": "A Faint Warmth", "note": "Barely there. You know it is there.", "secs": 300, "slot": "glow", "tier": 1}, {"id": "g2", "cost": 7.2e+24, "name": "Employee Of The Month Sheen", "note": "The particular gold of a laminated certificate.", "secs": 1500, "slot": "glow", "tier": 2}, {"id": "g3", "cost": 8.6e+25, "name": "Executive Blue", "note": "The colour of a screensaver in a room nobody books.", "secs": 7500, "slot": "glow", "tier": 3}, {"id": "g4", "cost": 1e+27, "name": "Fire Drill Red", "note": "People instinctively file toward the exit when you walk past.", "secs": 37500, "slot": "glow", "tier": 4}, {"id": "g5", "cost": 1.2e+28, "name": "Server Room Green", "note": "You hum slightly. Nobody has mentioned it.", "secs": 187500, "slot": "glow", "tier": 5}, {"id": "g6", "cost": 1.5e+29, "name": "Unapproved Purple", "note": "Not in the brand guidelines. Not addressed by the brand guidelines.", "secs": 937500, "slot": "glow", "tier": 6}, {"id": "s1", "cost": 3e+24, "name": "Good Posture", "note": "You are not taller. You simply take up more of the room.", "secs": 900, "slot": "size", "tier": 1}, {"id": "s2", "cost": 3.6e+25, "name": "Presence", "note": "People stop talking slightly before you arrive.", "secs": 6000, "slot": "size", "tier": 2}, {"id": "s3", "cost": 4.3e+26, "name": "Corner Office Energy", "note": "Doorways are now a consideration.", "secs": 40000, "slot": "size", "tier": 3}, {"id": "h1", "cost": 9e+23, "name": "A Mug You Never Wash", "note": "It has a ring in it older than most of the staff.", "secs": 450, "slot": "held", "tier": 1}, {"id": "h2", "cost": 1.1e+25, "name": "A Clipboard", "note": "You carry it everywhere. Nobody asks what is on it. That is the trick.", "secs": 2700, "slot": "held", "tier": 2}, {"id": "h3", "cost": 1.3e+26, "name": "A Briefcase With Nothing In It", "note": "Weightless. Convincing.", "secs": 16000, "slot": "held", "tier": 3}, {"id": "h4", "cost": 1.6e+27, "name": "A Trophy For Something", "note": "The plaque has been buffed smooth. Nobody remembers the category.", "secs": 96000, "slot": "held", "tier": 4}, {"id": "h5", "cost": 1.9e+28, "name": "The Golden Stapler", "note": "It does not staple. It has not stapled in years. It is beyond stapling.", "secs": 576000, "slot": "held", "tier": 5}, {"id": "a1", "cost": 4e+25, "name": "Perpetual Dust Motes", "note": "Lit from somewhere. There is no window on that side.", "secs": 1800, "slot": "aura", "tier": 1}, {"id": "a2", "cost": 4.8e+26, "name": "A Faint Shimmer", "note": "Facilities have inspected it twice and filed nothing.", "secs": 12000, "slot": "aura", "tier": 2}, {"id": "a3", "cost": 5.8e+27, "name": "Small Contained Flames", "note": "Signed off by nobody. Questioned by nobody.", "secs": 80000, "slot": "aura", "tier": 3}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('vend_prizes','[{"w": 22, "id": "crisps", "mins": 10, "mult": 1.1, "text": "A bag of crisps. Flavour unclear. Eaten anyway."}, {"w": 18, "id": "choc", "mins": 8, "mult": 1.2, "text": "A chocolate bar from a brand that no longer exists."}, {"w": 14, "id": "stuck", "kind": "none", "text": "It hangs on the coil. You shake the machine. It does not move."}, {"w": 10, "id": "two", "mins": 10, "mult": 1.35, "text": "Two fall out. You look around. You take both."}, {"w": 12, "id": "wrong", "mins": 14, "mult": 1.05, "text": "You get the one below it. It is not what you wanted. It is fine."}, {"w": 10, "id": "coins", "kind": "pp", "text": "Your money comes back plus somebody else''s.", "amount": 90}, {"w": 8, "id": "ancient", "mins": 8, "mult": 0.92, "text": "Best before 2019. You are going to eat it and you know it."}, {"w": 4, "id": "jack", "kind": "pp", "text": "The whole row drops. Every single one. You make two trips.", "amount": 900}, {"w": 2, "id": "knows", "mins": 12, "mult": 2, "text": "It dispenses your exact favourite, unprompted. You feel watched."}]'::jsonb);
INSERT INTO public.catalog(key,data) VALUES ('weekly_pins','[{"id": "p01", "hue": "#C9A253", "name": "Five Year Pin", "note": "Nobody can confirm the five years.", "secs": 2400, "glyph": "\u2605"}, {"id": "p02", "hue": "#B23B2E", "name": "Fire Warden", "note": "You did not volunteer. You were volunteered.", "secs": 3000, "glyph": "\u2691"}, {"id": "p03", "hue": "#C0392B", "name": "First Aid Certified", "note": "Expired. Still wearing it.", "secs": 2200, "glyph": "\u271a"}, {"id": "p04", "hue": "#D9B44A", "name": "Employee Of Some Month", "note": "The month has been scratched off.", "secs": 3600, "glyph": "\u2726"}, {"id": "p05", "hue": "#4A5568", "name": "The Umbrella", "note": "Left in the stand for two years. Now yours.", "secs": 2000, "glyph": "\u2602"}, {"id": "p06", "hue": "#7C5230", "name": "Coffee Club, Founding Member", "note": "There are four members. Three have left.", "secs": 2600, "glyph": "\u2615"}, {"id": "p07", "hue": "#6E756B", "name": "Health And Safety Rep", "note": "Comes with a lanyard and a grievance.", "secs": 3200, "glyph": "\u2699"}, {"id": "p08", "hue": "#5D8AA8", "name": "Frequent Flyer", "note": "Two trips. Both to the same regional office.", "secs": 3400, "glyph": "\u2708"}, {"id": "p09", "hue": "#3E4A6B", "name": "Night Shift Survivor", "note": "You have seen the building at 4am. It knows.", "secs": 4200, "glyph": "\u263e"}, {"id": "p10", "hue": "#E8B23C", "name": "Fastest Kettle", "note": "Contested. Never formally awarded.", "secs": 2800, "glyph": "\u26a1"}, {"id": "p11", "hue": "#7C6B8A", "name": "Office Playlist Custodian", "note": "Nobody else wanted it. Everybody has notes.", "secs": 2400, "glyph": "\u266a"}, {"id": "p12", "hue": "#8A9084", "name": "The Good Scissors", "note": "They live in your drawer now. Everybody knows.", "secs": 3000, "glyph": "\u2702"}, {"id": "p13", "hue": "#2C6B45", "name": "Plant Waterer", "note": "One plant is plastic. You water it anyway.", "secs": 2600, "glyph": "\u2618"}, {"id": "p14", "hue": "#9FC4D8", "name": "Snowflake Committee", "note": "Formed in December. Never disbanded.", "secs": 3800, "glyph": "\u2744"}, {"id": "p15", "hue": "#E0A93C", "name": "Window Seat", "note": "You did not ask. It was simply assigned.", "secs": 4600, "glyph": "\u2600"}, {"id": "p16", "hue": "#6B5433", "name": "Keeper Of The Key", "note": "To a cupboard nobody has opened since 2019.", "secs": 5200, "glyph": "\u2318"}, {"id": "p17", "hue": "#2C4A6B", "name": "Petty Cash Signatory", "note": "A power you have never once used.", "secs": 6000, "glyph": "\u25c8"}, {"id": "p18", "hue": "#A0522D", "name": "The Long Lunch", "note": "Ninety minutes. Unchallenged. Legendary.", "secs": 7000, "glyph": "\u25d1"}]'::jsonb);
